const userMessage = (content: string) => ({type: 'user_message', content});
const afterPendingWork = () => new Promise(resolve => setImmediate(resolve));

// Each run answers with its own number and then waits at its gate, so a test decides when it ends.
const gated = (runs: number) => {
  const sent: OutgoingMessage[] = [];
  const socket = {
    readyState: WebSocket.OPEN as number,
    send: (raw: string) => sent.push(JSON.parse(raw) as OutgoingMessage),
  };
  const ws = socket as unknown as WebSocket;
  const gates = Array.from({length: runs}, () => deferred());
  const handed: SessionEntry[][] = [];
  const processMessageStream = async function* (session: ChatSession): AsyncGenerator<MessageChunk> {
    const run = handed.length;
    handed.push(structuredClone(session.entries));
    yield text(`answer ${run}`);
    await gates[run].until;
    yield STOP;
  };
  const session: ChatSession = {sessionId: 's1', userId: 'u1', entries: []};
  const handle = createMessageHandler({processMessageStream} as unknown as ChatOrchestrator);

  return {
    session,
    handed,
    release: (run: number) => gates[run].release(),
    close: () => {
      socket.readyState = WebSocket.CLOSED;
    },
    frames: () => wire(sent),
    send: (raw: unknown) => handle(ws, session, raw),
  };
};

describe('one message at a time per session', () => {
  it('answers a second user_message only after the first has sent its stream_end, in the order they arrived', async () => {
    const h = gated(2);
    const first = h.send(userMessage('A'));
    const second = h.send(userMessage('B'));
    await afterPendingWork();
    h.release(0);
    await first;
    h.release(1);
    await second;

    const {entries} = h.session;
    expect({
      entries: entries.map(entry => `${entry.role} ${'content' in entry ? entry.content : ''}`),
      frames: h.frames(),
    }).toEqual({
      entries: ['user A', 'assistant answer 0', 'user B', 'assistant answer 1'],
      frames: [
        'upsert 0 user "A"',
        'upsert 1 assistant ""',
        'delta 1 "answer 0"',
        'commit 1',
        'stream_end',
        'upsert 2 user "B"',
        'upsert 3 assistant ""',
        'delta 3 "answer 1"',
        'commit 3',
        'stream_end',
      ],
    });
  });

  it('hands the second run a history whose first answer is finished, never one still streaming', async () => {
    const h = gated(2);
    const first = h.send(userMessage('A'));
    await afterPendingWork();
    const second = h.send(userMessage('B'));
    await afterPendingWork();
    h.release(0);
    await first;
    h.release(1);
    await second;

    expect(h.handed[1]).toEqual([
      {role: 'user', content: 'A', timestamp: expect.any(String)},
      {role: 'assistant', content: 'answer 0', timestamp: expect.any(String), isStreaming: false},
      {role: 'user', content: 'B', timestamp: expect.any(String)},
    ]);
  });

  it('answers a ping at once while a run is pending', async () => {
    const h = gated(1);
    const run = h.send(userMessage('A'));
    await afterPendingWork();
    void h.send({type: 'ping', timestamp: 7});
    await afterPendingWork();
    const beforeTheRunEnds = h.frames();
    h.release(0);
    await run;

    expect(beforeTheRunEnds).toEqual(['upsert 0 user "A"', 'upsert 1 assistant ""', 'delta 1 "answer 0"', 'pong 7']);
  });

  it('answers an invalid ping at once but an invalid user_message in turn, after the run in progress', async () => {
    const h = gated(1);
    const sends = [h.send(userMessage('A'))];
    await afterPendingWork();
    sends.push(h.send({type: 'ping'}), h.send(userMessage('')));
    await afterPendingWork();
    const beforeTheRunEnds = h.frames();
    h.release(0);
    await Promise.all(sends);

    expect({beforeTheRunEnds, after: h.frames().slice(beforeTheRunEnds.length)}).toEqual({
      beforeTheRunEnds: ['upsert 0 user "A"', 'upsert 1 assistant ""', 'delta 1 "answer 0"', 'error INVALID_MESSAGE'],
      after: ['commit 1', 'stream_end', 'error INVALID_MESSAGE', 'stream_end'],
    });
  });

  it('queues three messages sent in one tick before the handler returns, and answers them in that order', async () => {
    const queued = jest.spyOn(PerSessionLock.prototype, 'run');
    const h = gated(3);
    const sends = ['A', 'B', 'C'].map(content => h.send(userMessage(content)));
    const {calls} = queued.mock;
    const queuedBeforeAnyAwait = calls.length;
    for (const run of [0, 1, 2]) h.release(run);
    await Promise.all(sends);
    queued.mockRestore();

    const {entries} = h.session;
    expect({
      queuedBeforeAnyAwait,
      asked: entries.filter(entry => entry.role === 'user').map(entry => ('content' in entry ? entry.content : '')),
    }).toEqual({queuedBeforeAnyAwait: 3, asked: ['A', 'B', 'C']});
  });

  it('drops a queued message whose socket closed before its turn, without asking the model or recording it', async () => {
    const h = gated(2);
    const sends = [h.send(userMessage('A')), h.send(userMessage('B'))];
    await afterPendingWork();
    h.close();
    h.release(0);
    await Promise.all(sends);

    const {entries} = h.session;
    expect({
      asked: h.handed.length,
      entries: entries.map(entry => `${entry.role} ${'content' in entry ? entry.content : ''}`),
    }).toEqual({asked: 1, entries: ['user A', 'assistant answer 0']});
  });
});

describe('a turn whose socket closes', () => {
  it('abandons the turn mid-stream with no error and no stream_end, committing the cut-off answer as it stood', async () => {
    const gate = deferred();
    const h = harness([text('Hal'), text('lo there'), STOP], {pauseAfter: {chunks: 1, until: gate.until}});
    const connection = new AbortController();
    const turn = h.send(undefined, connection.signal);
    await afterPendingWork();
    const beforeClose = h.frames().length;
    connection.abort();
    gate.release();
    await turn;

    const [, answer] = h.session.entries;
    expect({afterClose: h.frames().slice(beforeClose), answer}).toEqual({
      afterClose: ['upsert 1 assistant "Hal"', 'commit 1'],
      answer: {role: 'assistant', content: 'Hal', timestamp: expect.any(String), isStreaming: false, truncated: true},
    });
  });

  it('drops a turn whose connection signal is already aborted: records nothing, asks nothing, sends nothing', async () => {
    const h = harness([text('hi'), STOP]);

    await h.send(undefined, AbortSignal.abort());

    const {calls} = h.processMessageStream.mock;
    expect({entries: h.session.entries, asked: calls.length, frames: h.frames()}).toEqual({
      entries: [],
      asked: 0,
      frames: [],
    });
  });

  it('hands the run its connection signal', async () => {
    const handed: Array<AbortSignal | undefined> = [];
    const orchestrator = {
      async *processMessageStream(
        _session: ChatSession,
        options?: {signal?: AbortSignal}
      ): AsyncGenerator<MessageChunk> {
        handed.push(options?.signal);
        yield STOP;
      },
    } as unknown as ChatOrchestrator;
    const ws = {send: () => undefined} as unknown as WebSocket;
    const session: ChatSession = {sessionId: 's1', userId: 'u1', entries: []};
    const connection = new AbortController();

    await createMessageHandler(orchestrator)(ws, session, {type: 'user_message', content: 'hello'}, connection.signal);

    expect({runs: handed.length, same: handed[0] === connection.signal}).toEqual({runs: 1, same: true});
  });

  it('answers a ping whose connection signal is aborted', async () => {
    const h = harness([]);

    await h.send({type: 'ping', timestamp: 9}, AbortSignal.abort());

    expect(h.frames()).toEqual(['pong 9']);
  });
});

describe('a tool call that fails', () => {
  it('completes a turn whose tool name the model invented: its answer streams, then stream_end, with no error frame', async () => {
    const frames = await turnOver({id: 'a', name: 'get_wether', input: {}}, new ToolRegistry());

    expect(outcomeOf(frames)).toEqual({answered: true, last: 'stream_end', errors: []});
  });

  it('completes a turn whose tool executor threw: its answer streams, then stream_end, with no error frame', async () => {
    const registry = new ToolRegistry();
    registry.register({name: 'lookup', description: 'Looks it up.', inputSchema: {type: 'object'}}, async () => {
      throw new Error('upstream down');
    });

    const frames = await turnOver({id: 'b', name: 'lookup', input: {}}, registry);

    expect(outcomeOf(frames)).toEqual({answered: true, last: 'stream_end', errors: []});
  });
});

// One real turn through the handler: the model asks for `call` and, handed its result, answers.
async function turnOver(call: ToolCall, registry: ToolRegistry): Promise<string[]> {
  let requests = 0;
  const provider: AIProvider = {
    async *sendMessage(): AsyncGenerator<MessageChunk> {
      requests++;
      const asks: MessageChunk[] = [
        {type: 'tool_use', toolCall: call},
        {type: 'stop', stopReason: 'tool_use'},
      ];
      yield* requests === 1 ? asks : [text('all done'), STOP];
    },
    async generateStructured<T>(): Promise<T> {
      return {} as T;
    },
  };
  const sent: OutgoingMessage[] = [];
  const ws = {send: (raw: string) => sent.push(JSON.parse(raw) as OutgoingMessage)} as unknown as WebSocket;
  const orchestrator = createChatOrchestrator(provider, new PromptBuilder({identity: 'Failure test.'}), registry);
  const session: ChatSession = {sessionId: 's1', userId: 'u1', entries: []};

  await createMessageHandler(orchestrator)(ws, session, userMessage('hello'));
  return wire(sent);
}

// What the client saw of the turn: whether the answer streamed, the last frame, and any error frames.
function outcomeOf(frames: string[]): {answered: boolean; last: string | undefined; errors: string[]} {
  return {
    answered: frames.some(frame => frame.startsWith('delta') && frame.endsWith(JSON.stringify('all done'))),
    last: frames.at(-1),
    errors: frames.filter(frame => frame.startsWith('error')),
  };
}

